/**
 * Transforms Storybook MDX docs from `@workday/canvas-tokens-docs` into plain Markdown under
 * `content/`:
 *  - removes all imports and Storybook specific items (`<Meta />`, `<Unstyled>`, ...)
 *  - removes layout-only HTML (`<br/>`)
 *  - replaces JSX components with a code block describing the component and its props
 *
 * generated by @claude.ai
 */
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {Parser} from 'acorn';
import jsx from 'acorn-jsx';
import {markdown, sources, outputs, packageRoot} from './config.mjs';

// Markdown puts sibling elements next to each other, which JSX parsing rejects: allow it.
class JSXParser extends Parser.extend(jsx()) {
  raise(pos, message) {
    if (message.startsWith('Adjacent JSX elements')) return;
    super.raise(pos, message);
  }
}

const {files: FILES, ignoredComponents: IGNORED_COMPONENTS} = markdown;

// ---------------------------------------------------------------------------------------------
// JSX -> code block
// ---------------------------------------------------------------------------------------------

/** Evaluates literal-only expressions (strings, numbers, arrays, objects...). Returns `undefined` when not static. */
function evaluate(node) {
  switch (node.type) {
    case 'Literal':
      return {value: node.value};
    case 'TemplateLiteral':
      return node.expressions.length === 0
        ? {value: node.quasis.map(q => q.value.cooked).join('')}
        : undefined;
    case 'UnaryExpression': {
      const arg = evaluate(node.argument);
      if (!arg || typeof arg.value !== 'number') return undefined;
      return {value: node.operator === '-' ? -arg.value : +arg.value};
    }
    case 'ArrayExpression': {
      const items = node.elements.map(el => (el ? evaluate(el) : undefined));
      return items.every(Boolean) ? {value: items.map(i => i.value)} : undefined;
    }
    case 'ObjectExpression': {
      const result = {};
      for (const prop of node.properties) {
        if (prop.type !== 'Property' || prop.computed) return undefined;
        const key = prop.key.type === 'Identifier' ? prop.key.name : prop.key.value;
        const val = evaluate(prop.value);
        if (!val) return undefined;
        result[key] = val.value;
      }
      return {value: result};
    }
    default:
      return undefined;
  }
}

const format = value => JSON.stringify(value, null, 2);

function attributeValue(attr, source) {
  if (attr.value === null) return 'true'; // <Comp disabled />
  if (attr.value.type === 'Literal') return JSON.stringify(attr.value.value);
  if (attr.value.type === 'JSXExpressionContainer') {
    const evaluated = evaluate(attr.value.expression);
    if (evaluated) return format(evaluated.value);
    // Not static (identifiers, calls, ...): keep the original source
    return source.slice(attr.value.expression.start, attr.value.expression.end);
  }
  return source.slice(attr.value.start, attr.value.end);
}

const elementName = name => {
  if (name.type === 'JSXMemberExpression')
    return `${elementName(name.object)}.${name.property.name}`;
  return name.name;
};

function componentToCodeBlock(element, source) {
  const opening = element.openingElement;
  const lines = [`component: ${elementName(opening.name)}`];
  for (const attr of opening.attributes) {
    if (attr.type === 'JSXSpreadAttribute') {
      lines.push(`...: ${source.slice(attr.argument.start, attr.argument.end)}`);
    } else {
      lines.push(`${attr.name.name}: ${attributeValue(attr, source)}`);
    }
  }
  return lines.join('\n');
}

// ---------------------------------------------------------------------------------------------
// MDX -> Markdown
// ---------------------------------------------------------------------------------------------

const IMPORT_RE = /^import\s+(?:([\s\S]*?)\s+from\s+)?(['"])([^'"]+)\2;?[ \t]*$/;

/** Removes top-level imports (not the ones inside code fences) and returns Storybook import names. */
function stripImports(text) {
  const storybookNames = new Set();
  const out = [];
  const lines = text.split('\n');
  let fence = null;

  for (let i = 0; i < lines.length; i++) {
    const fenceMatch = lines[i].match(/^\s*(`{3,}|~{3,})/);
    if (fenceMatch) {
      if (!fence) fence = fenceMatch[1];
      else if (fenceMatch[1][0] === fence[0] && fenceMatch[1].length >= fence.length) fence = null;
    }
    if (fence || fenceMatch || !/^import[\s{'"]/.test(lines[i])) {
      out.push(lines[i]);
      continue;
    }

    // Collect a (possibly multi-line) import statement
    let statement = lines[i];
    while (!IMPORT_RE.test(statement) && i + 1 < lines.length) statement += '\n' + lines[++i];
    const match = statement.match(IMPORT_RE);
    if (match && match[3].startsWith('@storybook/')) {
      for (const [, name] of (match[1] || '').matchAll(/([A-Za-z_$][\w$]*)\s*(?:,|\}|$)/g)) {
        storybookNames.add(name);
      }
    }
  }
  return {text: out.join('\n'), storybookNames};
}

function parseElementAt(source, start, label) {
  try {
    // Parse a single element; unlike `parseExpressionAt` this tolerates trailing content
    const parser = new JSXParser({ecmaVersion: 'latest'}, source, start);
    parser.nextToken();
    return parser.parseExprAtom();
  } catch (error) {
    throw new Error(`Cannot parse ${label}: ${error.message}`);
  }
}

export function transformMdx(input, file = 'input') {
  const {text, storybookNames} = stripImports(input.replace(/\r\n/g, '\n'));
  const lines = text.split('\n');
  const out = [];

  let fence = null;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const fenceMatch = line.match(/^\s*(`{3,}|~{3,})/);
    if (fenceMatch) {
      if (!fence) fence = fenceMatch[1];
      else if (fenceMatch[1][0] === fence[0] && fenceMatch[1].length >= fence.length) fence = null;
      out.push(line);
      continue;
    }
    if (fence) {
      out.push(line);
      continue;
    }

    // Layout only HTML such as <br/>
    if (/^\s*<br\s*\/?>\s*$/i.test(line)) continue;

    // Storybook closing tags, e.g. </Unstyled>
    const closing = line.match(/^\s*<\/([A-Z][\w.]*)>\s*$/);
    if (closing && storybookNames.has(closing[1])) continue;

    const opening = line.match(/^(\s*)<([A-Z][\w.]*)/);
    if (!opening) {
      out.push(line);
      continue;
    }

    const name = opening[2];

    // Storybook wrappers that only contain markdown (<Unstyled>): drop the tag, content stays
    if (storybookNames.has(name) && /^\s*<[A-Z][\w.]*(\s[^>]*)?(?<!\/)>\s*$/.test(line)) continue;

    // Parse the full JSX element, possibly spanning many lines, starting at this line
    const source = lines.slice(i).join('\n');
    const start = opening[1].length;
    const element = parseElementAt(source, start, `${file}: <${name}> at line ${i + 1}`);
    const consumedLines = source.slice(0, element.end).split('\n').length;

    // Storybook items (<Meta ... />) and ignored components are removed entirely; any other
    // component is replaced by a code block describing it
    if (!storybookNames.has(name) && !IGNORED_COMPONENTS.includes(name)) {
      out.push('```', componentToCodeBlock(element, source), '```');
    }
    i += consumedLines - 1;
  }

  return (
    out
      .join('\n')
      .replace(/[ \t]+$/gm, '')
      .replace(/\n{3,}/g, '\n\n')
      .trim()
      // a thematic break left dangling at the end after removing a trailing component
      .replace(/\n+---$/, '') + '\n'
  );
}

function main() {
  fs.rmSync(outputs.content, {recursive: true, force: true});

  for (const file of FILES) {
    const source = path.join(sources.stories, file);
    const target = path.join(outputs.content, file.replace(/\.mdx$/, '.md'));
    const result = transformMdx(fs.readFileSync(source, 'utf8'), file);

    fs.mkdirSync(path.dirname(target), {recursive: true});
    fs.writeFileSync(target, result);
    console.log(`content: ${path.relative(packageRoot, target)}`);
  }
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
